import bisect
from collections import defaultdict
from typing import List

class Solution:
    def subarrayMajority(self, nums: List[int], queries: List[List[int]]) -> List[int]:
        pos = defaultdict(list)
        for idx, val in enumerate(nums):
            pos[val].append(idx)

        ans = []
        for l, r, threshold in queries:
            window_size = r - l + 1
            if window_size < threshold:
                ans.append(-1)
                continue

            # Check unique elements occurring in the range
            found = -1
            # We can scan candidates with frequency >= threshold
            for val, indices in pos.items():
                if len(indices) < threshold:
                    continue
                # Count occurrences in range [l, r]
                right_idx = bisect.bisect_right(indices, r)
                left_idx = bisect.bisect_left(indices, l)
                cnt = right_idx - left_idx
                if cnt >= threshold:
                    if found == -1 or val < found:
                        found = val
            ans.append(found)

        return ans

#include <vector>
#include <unordered_map>
#include <algorithm>

class Solution {
public:
    std::vector<int> subarrayMajority(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
        std::unordered_map<int, std::vector<int>> pos;
        for (int i = 0; i < (int)nums.size(); ++i) {
            pos[nums[i]].push_back(i);
        }

        std::vector<int> ans;
        ans.reserve(queries.size());

        for (const auto& q : queries) {
            int l = q[0], r = q[1], threshold = q[2];
            if (r - l + 1 < threshold) {
                ans.push_back(-1);
                continue;
            }
            int found = -1;
            for (const auto& [val, indices] : pos) {
                if ((int)indices.size() < threshold) continue;
                auto it_r = std::upper_bound(indices.begin(), indices.end(), r);
                auto it_l = std::lower_bound(indices.begin(), indices.end(), l);
                int cnt = std::distance(it_l, it_r);
                if (cnt >= threshold) {
                    if (found == -1 || val < found) {
                        found = val;
                    }
                }
            }
            ans.push_back(found);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int[] subarrayMajority(int[] nums, int[][] queries) {
        Map<Integer, List<Integer>> pos = new HashMap<>();
        for (int i = 0; i < nums.length; i++) {
            pos.computeIfAbsent(nums[i], k -> new ArrayList<>()).add(i);
        }

        int[] ans = new int[queries.length];
        for (int i = 0; i < queries.length; i++) {
            int l = queries[i][0], r = queries[i][1], threshold = queries[i][2];
            if (r - l + 1 < threshold) {
                ans[i] = -1;
                continue;
            }
            int found = -1;
            for (Map.Entry<Integer, List<Integer>> entry : pos.entrySet()) {
                List<Integer> indices = entry.getValue();
                if (indices.size() < threshold) continue;

                int rIdx = upperBound(indices, r);
                int lIdx = lowerBound(indices, l);
                int cnt = rIdx - lIdx;
                if (cnt >= threshold) {
                    int val = entry.getKey();
                    if (found == -1 || val < found) {
                        found = val;
                    }
                }
            }
            ans[i] = found;
        }
        return ans;
    }

    private int lowerBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (list.get(mid) >= target) high = mid;
            else low = mid + 1;
        }
        return low;
    }

    private int upperBound(List<Integer> list, int target) {
        int low = 0, high = list.size();
        while (low < high) {
            int mid = (low + high) >>> 1;
            if (list.get(mid) > target) high = mid;
            else low = mid + 1;
        }
        return low;
    }
}

var subarrayMajority = function(nums, queries) {
    const pos = new Map();
    for (let i = 0; i < nums.length; i++) {
        if (!pos.has(nums[i])) pos.set(nums[i], []);
        pos.get(nums[i]).push(i);
    }

    function lowerBound(arr, target) {
        let l = 0, r = arr.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (arr[mid] >= target) r = mid;
            else l = mid + 1;
        }
        return l;
    }

    function upperBound(arr, target) {
        let l = 0, r = arr.length;
        while (l < r) {
            const mid = (l + r) >> 1;
            if (arr[mid] > target) r = mid;
            else l = mid + 1;
        }
        return l;
    }

    const ans = [];
    for (const [l, r, threshold] of queries) {
        if (r - l + 1 < threshold) {
            ans.push(-1);
            continue;
        }
        let found = -1;
        for (const [val, indices] of pos.entries()) {
            if (indices.length < threshold) continue;
            const cnt = upperBound(indices, r) - lowerBound(indices, l);
            if (cnt >= threshold) {
                if (found == -1 || val < found) {
                    found = val;
                }
            }
        }
        ans.push(found);
    }
    return ans;
};
